    console.error(`usage: bun tests/fixtures/make-fixture.ts <outDir> [--scenario ${SCENARIOS.join("|")}] [--force]`);
    process.exit(2);
  }
  console.log(JSON.stringify(makeFixture(outDir, scenario, { force: args.includes("--force") }), null, 2));
}

